create table if not exists public.market_orders(id uuid primary key default gen_random_uuid(), account_id uuid not null, item_id text not null, side text not null check(side in('buy','sell')), unit_price bigint not null check(unit_price>0), original_quantity integer not null check(original_quantity>0), remaining_quantity integer not null check(remaining_quantity>=0), status text not null check(status in('open','filled','cancelled','expired')), idempotency_key text not null unique, created_at timestamptz not null default now());
create index if not exists market_order_book_idx on public.market_orders(item_id,side,status,unit_price,created_at);
create table if not exists public.market_trades(id uuid primary key default gen_random_uuid(), item_id text not null, buy_order_id uuid not null references public.market_orders(id), sell_order_id uuid not null references public.market_orders(id), unit_price bigint not null, quantity integer not null, sale_fee bigint not null, created_at timestamptz not null default now(), unique(buy_order_id,sell_order_id,created_at));
alter table public.market_orders enable row level security; alter table public.market_trades enable row level security;
create policy "read open market" on public.market_orders for select using(status='open' or account_id=auth.uid());
create policy "read market trades" on public.market_trades for select using(true);
